// Validate env vars and initialize execution metadata
const required=['KOMMO_BASE_URL','KOMMO_PIPELINE_ID','KOMMO_STATUS_NOVO_SEGUIDOR','KOMMO_STATUS_QUALIFICACAO','KOMMO_STATUS_INTERESSE_REAL','KOMMO_STATUS_ANDREA','KOMMO_STATUS_THAIS','OPENAI_API_KEY'];
const missing=required.filter(v=>!$env[v]);
if(missing.length>0) throw new Error('Missing n8n env vars: '+missing.join(', ')+'. Run setup-pipeline.js first.');

// Pass execution start time for telemetry
const item = $input.first();
item.json._execStart = Date.now();
item.json._execId = Math.random().toString(36).slice(2,10);
return [item];

const body=$input.first().json.body;
if(!body||!body.entry||!body.entry[0]) return [{json:{skip:true,reason:'No entry in payload'}}];
const entry=body.entry[0];
let eventType='unknown',senderId=null,senderUsername=null,message='',timestamp=new Date().toISOString();
if(entry.messaging&&entry.messaging.length>0){
  const msg=entry.messaging[0];
  senderId=msg.sender?String(msg.sender.id):null;
  eventType='dm';
  message=(msg.message&&msg.message.text)||'';
  if(msg.timestamp) timestamp=new Date(Number(msg.timestamp)).toISOString();
} else if(entry.changes&&entry.changes.length>0){
  const change=entry.changes[0];
  if(change.field==='comments'){
    eventType='comment';
    senderId=change.value&&change.value.from?String(change.value.from.id):null;
    senderUsername=change.value&&change.value.from?change.value.from.username:null;
    message=(change.value&&change.value.text)||'';
  } else if(change.field==='followers'||change.field==='follow'){
    eventType='follow';
    senderId=change.value?String(change.value.id||change.value.user_id):null;
    senderUsername=change.value?change.value.username:null;
  }
}
if(!senderId) return [{json:{skip:true,reason:'No sender ID'}}];
return [{json:{eventType,senderId,senderUsername:senderUsername||'ig_user_'+senderId,message,timestamp,skip:false}}];

const response=$input.first().json;
const prevData=$('Parse Instagram Event').first().json;
let contactId=null,contactExists=false,contactName=null;

// Handle Kommo API error responses gracefully
if(response && response.status && response.status >= 400) {
  // API returned error — treat as "not found" and proceed to create
  return [{json:{...prevData,contactId:null,contactExists:false,contactName:null,_kommoContactError:response.status}}];
}

if(response&&response._embedded&&response._embedded.contacts&&response._embedded.contacts.length>0){
  const c=response._embedded.contacts[0];
  contactId=c.id; contactExists=true; contactName=c.name;
}
return [{json:{...prevData,contactId,contactExists,contactName}}];

const prevData=$('Contact Exists?').first().json;
let contactId=prevData.contactId,contactName=prevData.contactName;
if(!contactId){
  const r=$input.first().json;
  // Handle create-contact API failure
  if(r && r._embedded && r._embedded.contacts && r._embedded.contacts.length>0){
    contactId=r._embedded.contacts[0].id;
    contactName=r._embedded.contacts[0].name;
  }
}
if(!contactId){
  // SAFE MODE: Cannot create contact. Log error but do not crash.
  // Return with _contactFailed flag so downstream nodes can degrade gracefully
  return [{json:{...prevData,contactId:null,contactName:prevData.senderUsername,_contactFailed:true}}];
}
return [{json:{...prevData,contactId,contactName:contactName||prevData.senderUsername}}];

const prevData=$('Merge Contact Data').first().json;

// If contact creation failed, skip lead operations
if(prevData._contactFailed){
  return [{json:{...prevData,leadId:null,leadExists:false,_leadSkipped:true}}];
}

const r=$input.first().json;
let leadId=null,leadExists=false;
if(r&&r._embedded&&r._embedded.leads&&r._embedded.leads.length>0){
  leadId=r._embedded.leads[0].id; leadExists=true;
}
return [{json:{...prevData,leadId,leadExists}}];

const prevData=$('Lead Exists?').first().json;

// If upstream failed, pass through
if(prevData._contactFailed || prevData._leadSkipped){
  return [{json:{...prevData,leadId:null,_leadFailed:true}}];
}

let leadId=prevData.leadId;
if(!leadId){
  const r=$input.first().json;
  if(r._embedded&&r._embedded.leads&&r._embedded.leads.length>0) leadId=r._embedded.leads[0].id;
}
if(!leadId){
  return [{json:{...prevData,leadId:null,_leadFailed:true}}];
}
return [{json:{...prevData,leadId,leadExists:prevData.leadExists}}];

const prevData=$('Merge Lead Data').first().json;

// SAFE MODE: deterministic responses when CRM operations failed
const SAFE_FALLBACK = 'Olá! Obrigado pelo seu contato com o Instituto Be Healthy. Estamos com um volume alto de mensagens, mas nossa equipe vai entrar em contato com você em breve!';
const SAFE_CLASSIFICATION = {lead_temperature:'cold',interest_area:'unknown',should_handoff:false,reasoning:'Safe mode - deterministic response'};

// Follow events: always deterministic (no AI cost)
if(prevData.eventType==='follow'){
  return [{json:{...prevData,aiResponse:'Olá! Bem-vindo(a) ao Instituto Be Healthy! Que bom ter você por aqui. Estamos aqui para cuidar da sua saúde e bem-estar. Se tiver alguma dúvida ou quiser saber mais sobre nossos tratamentos, é só nos chamar!',classification:{lead_temperature:'cold',interest_area:'unknown',should_handoff:false,reasoning:'New follower - deterministic greeting'},tokensUsed:0,_aiMode:'deterministic'}}];
}

// If CRM failed upstream, use safe mode but still try AI
if(prevData._leadFailed || prevData._contactFailed){
  return [{json:{...prevData,aiResponse:SAFE_FALLBACK,classification:SAFE_CLASSIFICATION,tokensUsed:0,_aiMode:'safe_crm_failed'}}];
}

// Load conversation history (last 5 CRM notes, capped)
let conversationHistory='';
if(prevData.leadExists&&prevData.leadId){
  try{
    const nr=await fetch($env.KOMMO_BASE_URL+'/leads/'+prevData.leadId+'/notes?limit=5&order=desc',{headers:{'Authorization':'Bearer '+$env.KOMMO_ACCESS_TOKEN},signal:AbortSignal.timeout(8000)});
    if(nr.ok){
      const nd=await nr.json();
      if(nd._embedded&&nd._embedded.notes){
        const notes=nd._embedded.notes.filter(n=>n.params&&n.params.text).map(n=>n.params.text).reverse();
        if(notes.length>0) conversationHistory='\n\nConversation history (last '+notes.length+'):\n'+notes.join('\n---\n');
      }
    }
  }catch(e){/* proceed without history */}
}

const systemPrompt=`You are the AI assistant for Instituto Be Healthy (@dr.felipefranca).
Speak in Brazilian Portuguese. Be empathetic, professional, welcoming.

SALES METHOD - SPIN:
- Situation: Ask about current health routine
- Problem: Identify health concerns or aesthetic goals
- Implication: Help understand impact of not addressing
- Need-Payoff: Guide toward Be Healthy solutions

CLASSIFICATION (output after every response):
- hot: Wants to schedule, mentions procedure, urgency, asks prices
- warm: Asks about treatments, actively engaged
- cold: Just followed/liked without clear interest
- unqualified: Not target audience, spam

INTEREST AREAS:
- weight_loss: Emagrecimento, dieta, saúde, metabolismo
- aesthetics: Estéticos, botox, preenchimento, pele, harmonização
- general: General health
- unknown: Cannot determine

STRICT RULES - NEVER:
- Give medical advice or diagnoses
- Prescribe medications
- Analyze exams
- Promise outcomes
- Schedule directly

For medical questions redirect: "Essa é uma pergunta muito importante! Para te dar a melhor orientação, seria ideal agendar uma consulta com o Dr. Felipe."

After your response output EXACTLY:
<classification>
{"lead_temperature":"hot","interest_area":"weight_loss","should_handoff":true,"reasoning":"brief"}
</classification>`;

const userMsg='['+prevData.eventType+'] '+(prevData.contactName||prevData.senderUsername)+': '+prevData.message+conversationHistory;

// OpenAI call with retry (2 attempts) and timeout (25s)
let aiText = null;
let tokensUsed = 0;
let lastError = null;

for(let attempt=0; attempt<2; attempt++){
  try{
    const oResp=await fetch('https://api.openai.com/v1/chat/completions',{
      method:'POST',
      headers:{'Authorization':'Bearer '+$env.OPENAI_API_KEY,'Content-Type':'application/json'},
      body:JSON.stringify({model:$env.OPENAI_MODEL||'gpt-4o',messages:[{role:'system',content:systemPrompt},{role:'user',content:userMsg}],max_tokens:400,temperature:0.7}),
      signal:AbortSignal.timeout(25000)
    });

    // Rate limit: if 429, wait and retry
    if(oResp.status===429 && attempt===0){
      const retryAfter = oResp.headers.get('retry-after');
      const waitMs = retryAfter ? Number(retryAfter)*1000 : 3000;
      await new Promise(r=>setTimeout(r,Math.min(waitMs,5000)));
      lastError='rate_limited_429';
      continue;
    }

    if(!oResp.ok){
      lastError='openai_'+oResp.status;
      const e=await oResp.text();
      if(attempt===0){await new Promise(r=>setTimeout(r,2000));continue;}
      break;
    }

    const aiData=await oResp.json();
    aiText=aiData.choices[0].message.content;
    tokensUsed=aiData.usage?aiData.usage.total_tokens:0;
    break;
  }catch(e){
    lastError=e.name==='TimeoutError'?'timeout_25s':e.message;
    if(attempt===0){await new Promise(r=>setTimeout(r,2000));continue;}
  }
}

// SAFE MODE: If AI completely failed after retries, use deterministic fallback
if(!aiText){
  return [{json:{...prevData,aiResponse:SAFE_FALLBACK,classification:SAFE_CLASSIFICATION,tokensUsed:0,_aiMode:'safe_ai_failed',_aiError:lastError}}];
}

// Parse classification with validation
let classification={lead_temperature:'cold',interest_area:'unknown',should_handoff:false,reasoning:'Not extracted'};
const cm=aiText.match(/<classification>\s*(\\{[\s\S]*?\\})\s*<\/classification>/);
if(cm){try{const p=JSON.parse(cm[1]);const vt=['hot','warm','cold','unqualified'];const va=['weight_loss','aesthetics','general','unknown'];classification={lead_temperature:vt.includes(p.lead_temperature)?p.lead_temperature:'cold',interest_area:va.includes(p.interest_area)?p.interest_area:'unknown',should_handoff:p.should_handoff===true,reasoning:String(p.reasoning||'')};}catch(e){}}
const cleanResp=aiText.replace(/<classification>[\s\S]*?<\/classification>/,'').trim();
return [{json:{...prevData,aiResponse:cleanResp,classification,tokensUsed,_aiMode:'live'}}];

const data=$input.first().json;

// If AI was in safe mode or CRM failed, skip classification
if(data._aiMode==='safe_crm_failed'||data._aiMode==='safe_ai_failed'||data._leadFailed){
  return [{json:{...data,targetStage:'Novo Seguidor',targetStatusId:Number($env.KOMMO_STATUS_NOVO_SEGUIDOR)||0,_classSkipped:true}}];
}

const {classification}=data;
const map={cold:{n:'Novo Seguidor',e:'KOMMO_STATUS_NOVO_SEGUIDOR'},warm:{n:'Qualificação',e:'KOMMO_STATUS_QUALIFICACAO'},hot:{n:'Interesse Real',e:'KOMMO_STATUS_INTERESSE_REAL'},unqualified:{n:'Novo Seguidor',e:'KOMMO_STATUS_NOVO_SEGUIDOR'}};
const stage=map[classification.lead_temperature]||map.cold;
const statusId=$env[stage.e];
if(!statusId){
  // Env var missing — degrade to cold, don't crash
  return [{json:{...data,targetStage:'Novo Seguidor',targetStatusId:Number($env.KOMMO_STATUS_NOVO_SEGUIDOR)||0,_classError:'Missing env '+stage.e}}];
}
return [{json:{...data,targetStage:stage.n,targetStatusId:Number(statusId)}}];

const data=$('Lead Classification').first().json;
const {classification,leadId}=data;

// If classification was skipped, don't handoff
if(data._classSkipped||data._leadFailed){
  return [{json:{leadId:leadId||0,operatorName:'none',operatorArea:'',responsibleUserId:0,targetStatusId:0,handoffMessage:'',aiResponse:data.aiResponse||'',classification:data.classification||{},senderId:data.senderId,eventType:data.eventType,_handoffSkipped:true}}];
}

const ops={weight_loss:{name:'Andrea',userId:14813416,envVar:'KOMMO_STATUS_ANDREA',area:'Emagrecimento e saúde'},aesthetics:{name:'Thais',userId:14832028,envVar:'KOMMO_STATUS_THAIS',area:'Procedimentos estéticos'}};
const op=ops[classification.interest_area]||ops.weight_loss;
const statusId=$env[op.envVar];
if(!statusId){
  return [{json:{...data,leadId,operatorName:op.name,operatorArea:op.area,responsibleUserId:op.userId,targetStatusId:0,handoffMessage:'Vou te conectar com '+op.name+', que vai poder te ajudar melhor! Ela vai entrar em contato em breve.',aiResponse:data.aiResponse,classification:data.classification,senderId:data.senderId,eventType:data.eventType,_handoffEnvError:'Missing '+op.envVar}}];
}
return [{json:{leadId,operatorName:op.name,operatorArea:op.area,responsibleUserId:op.userId,targetStatusId:Number(statusId),handoffMessage:'Vou te conectar com '+op.name+', que é especialista em '+op.area+' e vai poder te ajudar melhor! Ela vai entrar em contato em breve.',aiResponse:data.aiResponse,classification:data.classification,senderId:data.senderId,eventType:data.eventType}}];

const data=$('Resolve Handoff Operator').first().json;
if(data.eventType==='dm'&&data.senderId&&$env.META_ACCESS_TOKEN){
  try{
    const r=await fetch('https://graph.instagram.com/v21.0/me/messages',{method:'POST',headers:{'Authorization':'Bearer '+$env.META_ACCESS_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({recipient:{id:data.senderId},message:{text:data.handoffMessage}})});
    return [{json:{...data,igReplyStatus:r.ok?'sent':'failed'}}];
  }catch(e){return [{json:{...data,igReplyStatus:'error',igReplyError:e.message}}];}
}
return [{json:{...data,igReplyStatus:data.eventType!=='dm'?'not_dm':'no_meta_token'}}];

const data=$('Lead Classification').first().json;
if(data.eventType==='dm'&&data.senderId&&$env.META_ACCESS_TOKEN){
  try{
    const r=await fetch('https://graph.instagram.com/v21.0/me/messages',{method:'POST',headers:{'Authorization':'Bearer '+$env.META_ACCESS_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({recipient:{id:data.senderId},message:{text:data.aiResponse}})});
    return [{json:{...data,igReplyStatus:r.ok?'sent':'failed'}}];
  }catch(e){return [{json:{...data,igReplyStatus:'error',igReplyError:e.message}}];}
}
return [{json:{...data,igReplyStatus:data.eventType!=='dm'?'not_dm':'no_meta_token'}}];

// Error Telemetry: Log any execution errors as CRM notes
// This node runs at the end of the error path to capture failures

const data = $input.first().json;
const errors = [];

if(data._contactFailed) errors.push('Contact creation failed');
if(data._leadFailed) errors.push('Lead creation/lookup failed');
if(data._aiError) errors.push('AI error: '+data._aiError);
if(data._aiMode==='safe_ai_failed') errors.push('AI unavailable - safe mode used');
if(data._aiMode==='safe_crm_failed') errors.push('CRM failed - safe mode used');
if(data._classError) errors.push('Classification env error: '+data._classError);
if(data._handoffEnvError) errors.push('Handoff env error: '+data._handoffEnvError);
if(data._kommoContactError) errors.push('Kommo contact API error: '+data._kommoContactError);

// If there are errors and we have a lead ID, log to CRM
if(errors.length>0 && data.leadId && $env.KOMMO_BASE_URL && $env.KOMMO_ACCESS_TOKEN){
  const noteText = 'SYSTEM ERROR LOG\n'+
    'Timestamp: '+new Date().toISOString()+'\n'+
    'Lead ID: '+data.leadId+'\n'+
    'Event: '+(data.eventType||'unknown')+'\n'+
    'Sender: '+(data.senderUsername||'unknown')+'\n'+
    'Errors:\n- '+errors.join('\n- ')+'\n'+
    'AI Mode: '+(data._aiMode||'unknown')+'\n'+
    'Exec ID: '+(data._execId||'none');

  try{
    await fetch($env.KOMMO_BASE_URL+'/leads/'+data.leadId+'/notes',{
      method:'POST',
      headers:{'Authorization':'Bearer '+$env.KOMMO_ACCESS_TOKEN,'Content-Type':'application/json'},
      body:JSON.stringify([{note_type:'common',params:{text:noteText}}]),
      signal:AbortSignal.timeout(5000)
    });
  }catch(e){/* best effort */}
}

// Always pass data through
return [{json:{...data,_errors:errors,_errorCount:errors.length}}];

// Rate limit guard: prevent processing bursts
// Uses n8n static data to track recent executions
const now = Date.now();
const windowMs = 60000; // 1 minute window
const maxPerWindow = 30; // max 30 events per minute

// Use workflow static data for rate tracking
const staticData = $getWorkflowStaticData('global');
if(!staticData.eventTimestamps) staticData.eventTimestamps = [];

// Clean old entries
staticData.eventTimestamps = staticData.eventTimestamps.filter(t => now - t < windowMs);

if(staticData.eventTimestamps.length >= maxPerWindow){
  return [{json:{skip:true,reason:'Rate limit exceeded ('+maxPerWindow+'/min). Event dropped.'}}];
}

staticData.eventTimestamps.push(now);
return [$input.first()];
